extends "res://state_machine/state_machine.gd"

var PLAYER_STATE = preload("res://player/player_state.gd").PLAYER_STATE

@onready var idle: Node = $Idle
@onready var move: Node = $Move
@onready var jump: Node = $Jump
@onready var stagger: Node = $Stagger
@onready var attack: Node = $Attack

func _ready() -> void:
	states_map = {
		PLAYER_STATE.idle: idle,
		PLAYER_STATE.move: move,
		PLAYER_STATE.jump: jump,
		PLAYER_STATE.stagger: stagger,
		PLAYER_STATE.attack: attack,
	}


func _change_state(state_name: String) -> void:
	# The base state_machine interface this node extends does most of the work.
	if not _active:
		return
	if state_name in [PLAYER_STATE.stagger, PLAYER_STATE.jump, PLAYER_STATE.attack]:
		states_stack.push_front(states_map[state_name])
	if state_name == PLAYER_STATE.jump and current_state == move:
		jump.initialize(move.speed, move.velocity)

	super._change_state(state_name)


func _unhandled_input(input_event: InputEvent) -> void:
	# Here we only handle input that can interrupt states, attacking in this case,
	# otherwise we let the state node handle it.
	if input_event.is_action_pressed(PLAYER_STATE.attack):
		if current_state in [attack, stagger]:
			return

		_change_state(PLAYER_STATE.attack)
		return

	current_state.handle_input(input_event)

extends Node
# Base interface for a generic state machine.
# It handles initializing, setting the machine active or not
# delegating _physics_process, _input calls to the State nodes,
# and changing the current/active state.
# See the PlayerV2 scene for an example on how to use it.

signal state_changed(current_state: Node)

# You should set a starting node from the inspector or on the node that inherits
# from this state machine interface. If you don't, the game will default to
# the first state in the state machine's children.
@export var start_state: NodePath
var states_map := {}

var states_stack := []
var current_state: Node = null
var _active: bool = false:
	set(value):
		_active = value
		set_active(value)


func _enter_tree() -> void:
	var initial_state: Node
	if start_state.is_empty():
		# Children have not entered the tree yet during their parent's
		# _enter_tree(), so calling get_path() on get_child(0) would return
		# an empty NodePath. Resolve to the Node reference directly.
		initial_state = get_child(0)
	else:
		initial_state = get_node(start_state)
	for child in get_children():
		var err: bool = child.finished.connect(_change_state)
		if err:
			printerr(err)
	initialize(initial_state)


func initialize(initial_state: Node) -> void:
	_active = true
	states_stack.push_front(initial_state)
	current_state = states_stack[0]
	current_state.enter()


func set_active(value: bool) -> void:
	set_physics_process(value)
	set_process_input(value)
	if not _active:
		states_stack = []
		current_state = null


func _unhandled_input(input_event: InputEvent) -> void:
	current_state.handle_input(input_event)


func _physics_process(delta: float) -> void:
	current_state.update(delta)


func _on_animation_finished(anim_name: String) -> void:
	if not _active:
		return

	current_state._on_animation_finished(anim_name)


func _change_state(state_name: String) -> void:
	if not _active:
		return
	current_state.exit()

	if state_name == "previous":
		states_stack.pop_front()
	else:
		states_stack[0] = states_map[state_name]

	current_state = states_stack[0]
	state_changed.emit(current_state)

	if state_name != "previous":
		current_state.enter()

